-- BACKLOG-3473 MUTANT (generated by generate.mjs from the shipped files; do not hand-edit)
-- can_edit_checklist_templates does not check the organization's entitlement
-- targets: c05 c41
-- Runs INSIDE a control's transaction, after the prelude; rolled back with it.

CREATE OR REPLACE FUNCTION public.can_edit_checklist_templates(p_org_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
           SELECT 1
             FROM public.organization_members m
             JOIN public.organizations o ON o.id = m.organization_id
            WHERE m.organization_id = p_org_id
              AND m.user_id = (SELECT auth.uid())
              AND (m.role IN ('broker', 'admin', 'it_admin')
                   OR o.personal_owner_user_id = m.user_id)
         );
$$;

DO $proof$
BEGIN
  IF NOT (pg_get_functiondef('public.can_edit_checklist_templates(uuid)'::regprocedure) NOT LIKE '%check_feature_access%') THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('entitlement term dropped') AS mutation;
